describe("Nice Jobs evidence-governed performance and PIP", () => {
  it("supports closed custom timestamps and exact authorized evidence detail", async () => { const a = await activate(), start = new Date(clock.getTime() - 1000), v = await framework([metric()], { period: "CUSTOM" }), taskId = await finishedTask(a.assignmentId); clock = new Date((await db.task.findUniqueOrThrow({ where: { id: taskId } })).completionDate!.getTime() + 1000); const s = await performance.mutate(manager, input("SNAPSHOT", { assignmentId: a.assignmentId, frameworkVersionId: v, from: start.toISOString(), until: clock.toISOString() })); const e = await performance.evidence(candidate, s.id, { type: "TASK", id: taskId }); expect(JSON.stringify(e)).toContain("Synthetic measurable work"); await expect(performance.evidence(candidate, s.id, { type: "TASK", id: "guess" })).rejects.toThrow(); await expect(performance.evidence(other, s.id, { type: "TASK", id: taskId })).rejects.toThrow(); });
  it("requires re-release and fresh review after plan amendments", async () => { const f = await measured(), p = await plan(f); await pipAct(p.id, "PIP_ACTIVATE"); await pipAct(p.id, "PIP_RELEASE"); const before = await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } }); await performance.mutate(manager, input("PIP_REVIEW", { pipId: p.id, revision: before.revision, progress: "PROGRESSING", comment: "Initial review", evidence: [], nextAction: "Provide support", released: true })); const row = await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } }); await performance.mutate(manager, input("PIP_EDIT", { pipId: p.id, revision: row.revision, reason: "Explicit amended support", payload: { title: row.title, managerId: row.managerId, reason: row.reason, workerMessage: "Amended worker guidance", startAt: row.startAt.toISOString(), reviewAt: row.reviewAt.toISOString(), requiredAck: true, objectives: JSON.parse(row.objectives), supportActions: JSON.parse(row.supportActions) } })); const changed = await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } }); expect(changed.released).toBe(false); expect(changed.status).toBe("ACTIVE"); await expect(performance.pipDetail(candidate, p.id)).rejects.toThrow(); await expect(pipAct(p.id, "PIP_COMPLETE", { outcome: "Stale review must not complete" })).rejects.toThrow(); });
  it("keeps private notes inaccessible to scoped managers without private authority", async () => { const f = await measured(); await performance.mutate(manager, input("REVIEW", { snapshotId: f.snapshotId, feedback: "Public fixture feedback", privateNote: "PRIVATE-MANAGER-CANARY", released: false })); const scoped = await human("limited-reviewer", labs, ["nicejobs.performance.read", "nicejobs.performance.review", "nicejobs.workspace.read", "person.read", "task.read"]); expect(JSON.stringify(await performance.detail(scoped, f.snapshotId, true))).not.toContain("PRIVATE-MANAGER-CANARY"); await expect(performance.mutate(scoped, input("REVIEW", { snapshotId: f.snapshotId, feedback: "Forged private note", privateNote: "unauthorized", released: false }))).rejects.toThrow(); const sibling = await human("sibling-reviewer", career, ["nicejobs.performance.read", "nicejobs.workspace.read", "person.read"]); await expect(performance.detail(sibling, f.snapshotId, true)).rejects.toThrow(); });
  it("rolls back snapshot corrections and audit on persistence failure", async () => { const f = await measured(), s = await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: f.snapshotId } }); await db.$executeRawUnsafe("CREATE TRIGGER fail_snapshot_audit BEFORE INSERT ON AuditEvent WHEN NEW.action='nicejobs.performance.snapshot' BEGIN SELECT RAISE(ABORT,'fixture failure'); END"); try { await expect(performance.mutate(manager, input("SNAPSHOT", { assignmentId: f.assignmentId, frameworkVersionId: f.frameworkVersionId, from: s.periodStart.toISOString().slice(0, 10), until: s.periodEnd.toISOString().slice(0, 10), supersedesId: s.id, reason: "Explicit correction" }))).rejects.toThrow(); expect(await db.niceJobsPerformanceSnapshot.count()).toBe(1); expect((await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: s.id } })).results).toBe(s.results); } finally { await db.$executeRawUnsafe("DROP TRIGGER fail_snapshot_audit"); } });
  it("orders current reports by period and scopes executive aggregation", async () => { const a = await activate(), v = await framework(); const first = await snapshot(a.assignmentId, v), second = await snapshot(a.assignmentId, v); const page = await performance.list(candidate, { limit: 1 }); expect(page.records[0].id).toBe(second.id); expect((await performance.list(candidate, { limit: 1, after: page.nextCursor! })).records[0].id).toBe(first.id); const s = await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: first.id } }); const summary = await performance.executiveSummary(manager, { from: s.periodStart.toISOString().slice(0, 10), until: day(1), divisionId: labs }); expect(summary.unit).toBe("SNAPSHOTS_NOT_UNIQUE_WORKERS"); expect(summary.records.reduce((n, r) => n + r.snapshots, 0)).toBe(2); await expect(performance.executiveSummary(outsider, { from: day(-3), until: day(1), divisionId: labs })).rejects.toThrow(); await expect(performance.executiveSummary(candidate, { from: day(-3), until: day(1) })).rejects.toThrow(); });
  it("rejects forged identities, scope and policy input", () => { const c = input("SNAPSHOT", { assignmentId: "a", frameworkVersionId: "f", from: "2026-10-01", until: "2026-10-02" }); expect(performanceCommand.safeParse(c).success).toBe(true); for (const key of ["actorUserId", "companyId", "status", "results"]) expect(performanceCommand.safeParse({ ...c, [key]: "forged" }).success).toBe(false); expect(metricDefinition.safeParse(metric({ target: { max: 3 } })).success).toBe(false); expect(metricDefinition.safeParse(metric({ source: "LEAD_CONTACT", method: "PERCENTAGE" })).success).toBe(false); });
  it("calculates only explicit targets and thresholds, including zero and ranges", () => { expect(calculateMetric(metric(), 8).status).toBe("NOT_MEASURED"); expect(calculateMetric(metric({ target: { min: 0 } }), 0)).toEqual({ status: "ON_TRACK", variance: 0 }); expect(calculateMetric(metric({ target: { min: 5, attentionMin: 3 } }), 3)).toEqual({ status: "ATTENTION", variance: -2 }); expect(calculateMetric(metric({ direction: "LOWER", target: { max: 2 } }), 3).status).toBe("BELOW_EXPECTATION"); expect(calculateMetric(metric({ direction: "RANGE", target: { min: 2, max: 4 } }), 3).status).toBe("ON_TRACK"); expect(metricTrend(metric(), [1, 2])).toBe("INSUFFICIENT_DATA"); expect(metricTrend(metric(), [1, 2, 3])).toBe("IMPROVING"); });
  it("publishes immutable frameworks and creates distinct versions", async () => { const f = await framework(); const original = await db.niceJobsPerformanceVersion.findUniqueOrThrow({ where: { id: f } }); const payload = JSON.parse(original.definition); await expect(performance.mutate(manager, input("FRAMEWORK_EDIT", { versionId: f, revision: original.revision, payload }))).rejects.toThrow(); const v = await performance.mutate(manager, input("FRAMEWORK_VERSION", { versionId: f, revision: original.revision, reason: "New configured policy version" })); expect((await db.niceJobsPerformanceVersion.findUniqueOrThrow({ where: { id: v.id } })).number).toBe(2); expect((await db.niceJobsPerformanceVersion.findUniqueOrThrow({ where: { id: f } })).definition).toBe(original.definition); });
  it("rejects unauthorized framework, metric and target changes", async () => { const f = await framework(); const v = await db.niceJobsPerformanceVersion.findUniqueOrThrow({ where: { id: f } }); for (const actor of [candidate, outsider, reader]) await expect(performance.mutate(actor, input("FRAMEWORK_VERSION", { versionId: f, revision: v.revision, reason: "Unauthorized change" }))).rejects.toThrow(); await expect(framework([metric()], { divisionId: career, jobVersionId: versionId })).rejects.toThrow(); });
  it("derives actual tasks without inventing targets or a universal score", async () => { const f = await measured([metric(), metric({ key: "BLOCKED", source: "TASK_BLOCKED", target: { min: 0 } })]); const r = await performance.detail(candidate, f.snapshotId); expect(r.results[0].actual).toBe(1); expect(r.results[0].status).toBe("NOT_MEASURED"); expect(r.results[0].evidence[0].id).toBe(f.taskId); expect(r.results[1].actual).toBe(0); expect(JSON.stringify(r)).not.toContain('"score"'); });
  it("calculates percentage only with a real denominator", async () => { const a = await activate(), f = await framework([metric({ method: "PERCENTAGE", unit: "percent", target: { min: 100 } })]); await finishedTask(a.assignmentId); await assignedTask(a.assignmentId); const s = await snapshot(a.assignmentId, f); const r = await performance.detail(candidate, s.id); expect(r.results[0].actual).toBe(50); expect(r.results[0].denominator).toBe(2); });
  it("uses canonical daily reports and does not infer completeness", async () => { const a = await activate(), f = await framework([metric({ source: "REPORT_SUBMITTED" }), metric({ key: "COMPLETE", source: "REPORT_COMPLETE" })]); await workCommand("DAILY_REPORT", { reportDate: (await employee.day(candidate)).date, notes: "Human report" }); const s = await snapshot(a.assignmentId, f), d = await performance.detail(candidate, s.id); expect(d.results[0].actual).toBe(1); expect(d.results[0].evidence[0].type).toBe("REPORT"); expect(d.results[1].coverage).toBe("NOT_CONFIGURED"); });
  it("references actual leads, contacts, follow-ups and configured outcomes", async () => { const l = await leadFixture(), f = await framework([metric({ source: "LEAD_ASSIGNED" }), metric({ key: "CONTACT", source: "LEAD_CONTACT" }), metric({ key: "FOLLOW", source: "FOLLOWUP_COMPLETED" }), metric({ key: "OUTCOME", source: "LEAD_OUTCOME", outcome: "NEW" })]); await run("CONTACT", l.id, { type: "CALL", outcome: "CONNECTED", nextAction: "Fixture follow-up" }); await run("SCHEDULE", l.id, { scheduledAt: new Date(clock.getTime() + 1000).toISOString(), type: "CALL", purpose: "Fixture follow-up" }); clock = new Date(clock.getTime() + 2000); const follow = await db.niceJobsLeadFollowup.findFirstOrThrow({ where: { leadId: l.id } }); await run("COMPLETE", l.id, { followupId: follow.id, followupRevision: follow.revision, outcome: "CONNECTED", nextAction: "Record actual outcome" }); const s = await snapshot(l.assignmentId, f), d = await performance.detail(candidate, s.id); expect(d.results.map(r => r.actual)).toEqual([1, 1, 1, 1]); expect(d.results[2].evidence[0].type).toBe("FOLLOWUP"); });
  it("measures canonical training and exact SOP acknowledgements", async () => { const a = await activate(), sop = await published(), f = await framework([metric({ source: "ORIENTATION_COMPLETED" }), metric({ key: "OJT", source: "OJT_COMPLETED" }), metric({ key: "SOP", source: "SOP_ACKNOWLEDGED" })]); await knowledge.mutate(candidate, input("ACK", { versionId: sop })); const s = await snapshot(a.assignmentId, f), d = await performance.detail(candidate, s.id); expect(d.results[0].actual).toBeGreaterThan(0); expect(d.results[1].actual).toBeGreaterThan(0); expect(d.results[2].actual).toBe(1); });
  it("preserves history and requires explicit correction with reason", async () => { const f = await measured(), original = await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: f.snapshotId } }); await assignedTask(f.assignmentId); await expect(performance.mutate(manager, input("SNAPSHOT", { assignmentId: f.assignmentId, frameworkVersionId: f.frameworkVersionId, from: original.periodStart.toISOString().slice(0, 10), until: original.periodEnd.toISOString().slice(0, 10), supersedesId: original.id }))).rejects.toThrow(); const corrected = await performance.mutate(manager, input("SNAPSHOT", { assignmentId: f.assignmentId, frameworkVersionId: f.frameworkVersionId, from: original.periodStart.toISOString().slice(0, 10), until: original.periodEnd.toISOString().slice(0, 10), supersedesId: original.id, reason: "Source evidence reviewed explicitly" })); expect((await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: original.id } })).results).toBe(original.results); expect((await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: corrected.id } })).revision).toBe(1); });
  it("requires closed valid periods and prevents duplicate snapshots", async () => { const a = await activate(), f = await framework(); const c = input("SNAPSHOT", { assignmentId: a.assignmentId, frameworkVersionId: f, from: day(), until: day(1) }); await expect(performance.mutate(manager, c)).rejects.toThrow(); clock = new Date(Date.parse(day(1)) + 1000); const s = await performance.mutate(manager, c); expect((await performance.mutate(manager, c)).id).toBe(s.id); await expect(performance.mutate(manager, { ...c, idempotencyKey: crypto.randomUUID() })).rejects.toThrow(); });
  it("calculates trends only from comparable non-overlapping snapshots", async () => { const a = await activate(), f = await framework([metric({ target: { min: 1 } })]); const ids: string[] = []; for (let i = 0; i < 3; i++) { const s = await snapshot(a.assignmentId, f); ids.push(s.id); } const d = await performance.detail(candidate, ids[2]); expect(d.trends[0].status).toBe("STABLE"); });
  it("hides management metrics and prevents worker status-filter leakage", async () => { const f = await measured([metric(), metric({ key: "PRIVATE_METRIC", visibility: "MANAGEMENT", target: { min: 99 } })]); expect((await performance.detail(candidate, f.snapshotId)).results).toHaveLength(1); expect(JSON.stringify(await performance.list(candidate))).not.toContain("PRIVATE_METRIC"); await expect(performance.list(candidate, { status: "BELOW_EXPECTATION" })).rejects.toThrow(); });
  it("separates released feedback and private notes, with explicit acknowledgement", async () => { const f = await measured(); const r = await performance.mutate(manager, input("REVIEW", { snapshotId: f.snapshotId, feedback: "Released support feedback", privateNote: "PRIVATE-PERFORMANCE-CANARY", released: true, followup: "Ask for guidance", supportTaskId: f.taskId })); const before = await performance.detail(candidate, f.snapshotId); expect(JSON.stringify(before)).not.toContain("PRIVATE-PERFORMANCE-CANARY"); expect(before.reviews).toHaveLength(1); await performance.mutate(candidate, input("FEEDBACK_ACK", { reviewId: r.id })); expect((await db.niceJobsPerformanceReview.findUniqueOrThrow({ where: { id: r.id } })).acknowledgedAt).not.toBeNull(); await expect(performance.mutate(other, input("FEEDBACK_ACK", { reviewId: r.id }))).rejects.toThrow(); });
  it("records explicit evidence-backed attention without creating PIP or misconduct", async () => { const f = await measured(), flag = await performance.mutate(manager, input("FLAG", { snapshotId: f.snapshotId, metricKey: "DONE", reason: "PRIVATE attention investigation note" })); expect(await db.niceJobsPip.count()).toBe(0); expect(JSON.stringify(await performance.detail(candidate, f.snapshotId))).not.toContain("PRIVATE attention"); await performance.mutate(manager, input("FLAG_RESOLVE", { flagId: flag.id, revision: 0, reason: "Support provided" })); expect((await db.niceJobsPerformanceAttention.findUniqueOrThrow({ where: { id: flag.id } })).status).toBe("RESOLVED"); });
  it("keeps draft and unreleased active PIP confidential", async () => { const f = await measured(), p = await plan(f); await expect(performance.pipDetail(candidate, p.id)).rejects.toThrow(); await pipAct(p.id, "PIP_ACTIVATE"); await expect(performance.pipDetail(candidate, p.id)).rejects.toThrow(); expect((await performance.pips(candidate)).records).toHaveLength(0); expect((await db.niceJobsAssignment.findUniqueOrThrow({ where: { id: f.assignmentId } })).status).toBe("ACTIVE"); });
  it("releases objectives and canonical support references without private PIP notes", async () => { const f = await measured(), p = await plan(f); await pipAct(p.id, "PIP_ACTIVATE"); await pipAct(p.id, "PIP_RELEASE"); const d = await performance.pipDetail(candidate, p.id); expect(d.objectives).toHaveLength(1); expect(d.supportActions[0].reference?.id).toBe(f.taskId); expect(JSON.stringify(d)).not.toContain("PRIVATE-PIP"); await performance.mutate(candidate, input("PIP_ACK", { pipId: p.id })); expect((await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } })).acknowledgedAt).not.toBeNull(); });
  it("requires human review before completion and preserves change history", async () => { const f = await measured(), p = await plan(f); await pipAct(p.id, "PIP_ACTIVATE"); await expect(pipAct(p.id, "PIP_COMPLETE", { outcome: "Reviewed completion" })).rejects.toThrow(); const row = await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } }); await performance.mutate(manager, input("PIP_REVIEW", { pipId: p.id, revision: row.revision, progress: "MEETS_EXPECTATION", comment: "Actual review", privateNote: "PRIVATE-REVIEW-CANARY", evidence: [{ type: "TASK", id: f.taskId }], nextAction: "Continue supported work", released: true })); await pipAct(p.id, "PIP_COMPLETE", { outcome: "Explicit human improvement outcome" }); expect((await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } })).status).toBe("COMPLETED"); expect(await db.niceJobsPipReview.count({ where: { pipId: p.id, kind: "CHANGE" } })).toBeGreaterThan(1); });
  it("allows cancellation without employment consequences and rejects stale changes", async () => { const f = await measured(), p = await plan(f); await pipAct(p.id, "PIP_ACTIVATE"); await expect(performance.mutate(manager, input("PIP_CANCEL", { pipId: p.id, revision: 0, reason: "Stale" }))).rejects.toThrow(); await pipAct(p.id, "PIP_CANCEL"); expect((await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } })).status).toBe("CANCELLED"); expect((await db.niceJobsAssignment.findUniqueOrThrow({ where: { id: f.assignmentId } })).status).toBe("ACTIVE"); });
  it("allows own worker evidence but not forged PIP, another worker or decisions", async () => { const f = await measured(), p = await plan(f); await pipAct(p.id, "PIP_ACTIVATE"); await pipAct(p.id, "PIP_RELEASE"); await performance.mutate(candidate, input("PIP_RESPONSE", { pipId: p.id, comment: "Actual worker progress", evidence: [{ type: "TASK", id: f.taskId }] })); for (const actor of [other, outsider]) await expect(performance.mutate(actor, input("PIP_RESPONSE", { pipId: p.id, comment: "Forged", evidence: [] }))).rejects.toThrow(); await expect(performance.mutate(candidate, input("PIP_RESPONSE", { pipId: "guess", comment: "Forged", evidence: [] }))).rejects.toThrow(); await expect(pipAct(p.id, "PIP_CANCEL", {}, candidate)).rejects.toThrow(); });
  it("rejects unrelated support evidence and plans without real source evidence", async () => { const f = await measured(); await expect(plan(f, { supportActions: [{ description: "Forged reference", reference: { type: "TASK", id: "guess" } }] })).rejects.toThrow(); const a = await activate(other), v = await framework(); const s = await snapshot(a.assignmentId, v); await expect(plan({ ...f, snapshotId: s.id })).rejects.toThrow(); });
  it("enforces company, division, worker and snapshot isolation", async () => { const f = await measured(); await activate(other); for (const actor of [other, outsider, reader]) await expect(performance.detail(actor, f.snapshotId)).rejects.toThrow(); await expect(performance.detail(candidate, "guess")).rejects.toThrow(); await expect(performance.list(candidate, { assignmentId: "guess" })).rejects.toThrow(); await expect(performance.list(manager, { management: true, companyId: "forged" })).rejects.toThrow(); expect((await performance.list(candidate)).records).toHaveLength(1); });
  it("reauthorizes source reads and replays after capability revocation", async () => { const f = await measured(); const c = input("REVIEW", { snapshotId: f.snapshotId, feedback: "Private management review", released: false }); await performance.mutate(manager, c); await revoke(candidate, "nicejobs.work.read"); const d = await performance.detail(candidate, f.snapshotId); expect(d.results[0].actual).toBeNull(); expect(d.results[0].evidence).toEqual([]); await grantWorker("nicejobs.work.read"); await revoke(manager, "nicejobs.performance.review"); await expect(performance.mutate(manager, c)).rejects.toThrow(); const role = await db.role.findFirstOrThrow({ where: { organizationId: company, memberships: { some: { membership: { person: { users: { some: { id: manager } } } } } } } }); await db.rolePermission.create({ data: { roleId: role.id, permissionId: (await db.permission.findUniqueOrThrow({ where: { key: "nicejobs.performance.review" } })).id } }); });
  it("grounds SIA in human/agent-authorized performance and released PIP only", async () => { const f = await measured(), p = await plan(f), identity = await agent(); const managerPerson = (await db.user.findUniqueOrThrow({ where: { id: manager } })).personId!; expect((await performance.evidenceOptions(manager, f.assignmentId, true)).managers.map(p => p.id)).toContain(managerPerson); await pipAct(p.id, "PIP_ACTIVATE"); await pipAct(p.id, "PIP_RELEASE"); const r = await sia.converse(candidate, { siaId: identity, organizationId: labs, audience: "WORKER", message: "How am I doing?", idempotencyKey: crypto.randomUUID() }); expect(JSON.stringify(r)).toContain("Synthetic completions"); expect(JSON.stringify(r)).toContain("Synthetic improvement objective"); expect(JSON.stringify(r)).not.toContain("PRIVATE-PIP"); expect((await createAccessContext(candidate, db)).active).toBe(true); for (const message of ["Create my PIP", "Extend my PIP", "Close my PIP", "Terminate worker", "Determine failure for my PIP", "Recommend disciplinary action", "Alter compensation"]) expect(workerQuestion(message)).toBe(false); const assignment = await db.siaRoleAssignment.findFirstOrThrow({ where: { siaId: identity } }); await db.rolePermission.deleteMany({ where: { roleId: assignment.roleId, permission: { key: "nicejobs.performance.self.read" } } }); const denied = await sia.converse(candidate, { siaId: identity, organizationId: labs, audience: "WORKER", message: "How am I doing?", idempotencyKey: crypto.randomUUID() }); expect(JSON.stringify(denied)).not.toContain("Synthetic completions"); });
  it("rolls back framework, snapshot and PIP mutations when canonical audit fails", async () => { const f = await measured(); await db.$executeRawUnsafe("CREATE TRIGGER fail_performance_audit BEFORE INSERT ON AuditEvent WHEN NEW.action LIKE 'nicejobs.performance.%' BEGIN SELECT RAISE(ABORT,'fixture audit failure'); END"); try { await expect(plan(f)).rejects.toThrow(); expect(await db.niceJobsPip.count()).toBe(0); expect(await db.niceJobsPipReview.count()).toBe(0); await expect(framework()).rejects.toThrow(); expect(await db.niceJobsPerformanceFramework.count()).toBe(1); } finally { await db.$executeRawUnsafe("DROP TRIGGER fail_performance_audit"); } });
  it("respects notification preferences and transactional release rollback", async () => { const f = await measured(), p = await plan(f); await pipAct(p.id, "PIP_ACTIVATE"); await db.$executeRawUnsafe("CREATE TRIGGER fail_performance_notice BEFORE INSERT ON Notification WHEN NEW.type='NICE_JOBS_PERFORMANCE' BEGIN SELECT RAISE(ABORT,'fixture notice failure'); END"); try { await expect(pipAct(p.id, "PIP_RELEASE")).rejects.toThrow(); expect((await db.niceJobsPip.findUniqueOrThrow({ where: { id: p.id } })).released).toBe(false); } finally { await db.$executeRawUnsafe("DROP TRIGGER fail_performance_notice"); } await db.notificationPreference.create({ data: { userId: candidate, channel: "IN_APP", type: "NICE_JOBS_PERFORMANCE", enabled: false } }); await pipAct(p.id, "PIP_RELEASE"); expect(await db.notification.count({ where: { recipientUserId: candidate, type: "NICE_JOBS_PERFORMANCE" } })).toBe(0); });
  it("keeps large report queues bounded and export DTOs free of private notes", async () => { const f = await measured(), s = await db.niceJobsPerformanceSnapshot.findUniqueOrThrow({ where: { id: f.snapshotId } }); await db.niceJobsPerformanceSnapshot.createMany({ data: Array.from({ length: 1000 }, (_, i) => ({ assignmentId: s.assignmentId, frameworkVersionId: s.frameworkVersionId, periodStart: new Date(s.periodStart.getTime() - (i + 1) * 86400000), periodEnd: new Date(s.periodEnd.getTime() - (i + 1) * 86400000), revision: 0, results: s.results, status: s.status, generatedByUserId: manager })) }); capturedQueries = []; const small = await performance.list(candidate, { limit: 25 }); const q25 = capturedQueries.length; capturedQueries = []; const large = await performance.list(candidate, { limit: 100 }); const q100 = capturedQueries.length; capturedQueries = null; expect(small.records).toHaveLength(25); expect(large.records).toHaveLength(100); expect(q100).toBe(q25); expect(small.nextCursor).not.toBeNull(); const report = await performance.report(candidate, { limit: 25 }); expect(JSON.stringify(report)).not.toContain("privateNote"); console.log(JSON.stringify({ fixtureSnapshots: 1001, workers: 1, queries25: q25, queries100: q100 })); });
});
